from security_client import SecretManagementClient

def rotate_secret_version(payload: dict, config: dict = None) -> dict:
    config = config or {}
    client = SecretManagementClient(vault_url=config.get('vault_url'))

    secret_id = payload['secret_id']
    version = payload.get('version')

    if version:
        secret_value = client.get_secret_version(secret_id, version)
    else:
        # For Azure Key Vault, getting the secret without a version defaults to the current active version
        secret_value = client.get_secret(secret_id)

    return {'secret_value': secret_value}

from security_client import SecretManagementClient
from security_models import SecretProperties
from datetime import datetime

def rotation_summary(config: dict = None) -> dict:
    config = config or {}
    client = SecretManagementClient(vault_url=config.get('vault_url'))

    secrets_summary = []
    for secret_properties in client.list_properties_of_secrets():
        properties = SecretProperties(
            id=secret_properties.id,
            name=secret_properties.name,
            enabled=secret_properties.enabled,
            expires_on=secret_properties.expires_on.timestamp() if secret_properties.expires_on else None,
            created_on=secret_properties.created_on.timestamp() if secret_properties.created_on else None,
            updated_on=secret_properties.updated_on.timestamp() if secret_properties.updated_on else None,
            tags=secret_properties.tags,
            content_type=secret_properties.content_type,
            recoverable_days=secret_properties.recoverable_days,
        )

        status = "Unknown"
        if properties.expires_on:
            expires_datetime = datetime.fromtimestamp(properties.expires_on)
            if expires_datetime < datetime.now():
                status = "Expired"
            elif (expires_datetime - datetime.now()).days < 30: # Example: expiring soon (within 30 days)
                status = "Expiring Soon"
            else:
                status = "Active"
        elif properties.updated_on:
             updated_datetime = datetime.fromtimestamp(properties.updated_on)
             if (datetime.now() - updated_datetime).days > 90: # Example: not updated in 90 days
                 status = "Stale (No Recent Update)"
             else:
                 status = "Active (Recently Updated)"
        else:
            status = "No Expiry/Update Info"

        secrets_summary.append({
            "secret_id": properties.name,
            "status": status,
            "expires_on": properties.expires_on,
            "updated_on": properties.updated_on,
            "tags": properties.tags,
        })

    return {"rotation_summary": secrets_summary}

from azure.cognitiveservices.vision.contentmoderator import ContentModeratorClient
from azure.cognitiveservices.vision.contentmoderator.models import Screen
from msrest.authentication import CognitiveServicesCredentials
from security_models import ContentSafetyRequest, ContentSafetyResponse
import os

def secret_label_safety(payload: dict, config: dict = None) -> dict:
    config = config or {}

    # Azure Content Moderator credentials
    subscription_key = os.environ.get("CONTENT_MODERATOR_KEY") or config.get('content_moderator_key')
    endpoint = os.environ.get("CONTENT_MODERATOR_ENDPOINT") or config.get('content_moderator_endpoint')

    if not subscription_key or not endpoint:
        raise ValueError("Content Moderator subscription key and endpoint must be provided or set in environment variables.")

    client = ContentModeratorClient(
        endpoint=endpoint,
        credentials=CognitiveServicesCredentials(subscription_key)
    )

    request_payload = ContentSafetyRequest(text=payload['text'])

    # Screen the text for profanity and other unsafe content
    screen_result: Screen = client.text_moderation.screen_text(text_content=request_payload.text, language='eng')

    is_safe = True
    moderation_result = {
        "profanity_score": screen_result.profanity_score,
        "terms": [],
        "classification": {}
    }

    if screen_result.terms:
        is_safe = False
        for term in screen_result.terms:
            moderation_result["terms"].append({"term": term.term, "index": term.index})

    if screen_result.classification:
        if screen_result.classification.review_recommended:
            is_safe = False
        moderation_result["classification"] = {
            "category1": screen_result.classification.category1.score if screen_result.classification.category1 else None,
            "category2": screen_result.classification.category2.score if screen_result.classification.category2 else None,
            "category3": screen_result.classification.category3.score if screen_result.classification.category3 else None,
            "review_recommended": screen_result.classification.review_recommended,
        }

    response = ContentSafetyResponse(is_safe=is_safe, moderation_result=moderation_result)
    return {"safety_check_result": response.__dict__}
